using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Match
{
public sealed class DimensionsFrontHUD:MonoBehaviour
{
private DimensionsFront front;private GUIStyle label,timer,overtime,team;private Texture2D pixel;private float nextFind;private void Awake(){pixel=new Texture2D(1,1);pixel.SetPixel(0,0,Color.white);pixel.Apply();}private void Update(){if(front==null&&Time.unscaledTime>=nextFind){nextFind=Time.unscaledTime+.5f;front=FindAnyObjectByType<DimensionsFront>();}}
private void OnGUI(){if(front==null||pixel==null)return;EnsureStyles();float width=Mathf.Min(520,Screen.width*.62f),x=(Screen.width-width)*.5f,y=22,barY=y+38,barH=14;Draw(new Rect(x,y,width,64),new Color(StylizedArtDirection.Ink.r,StylizedArtDirection.Ink.g,StylizedArtDirection.Ink.b,.88f));Draw(new Rect(x-3,y+8,3,48),StylizedArtDirection.ZeroEnergy);Draw(new Rect(x+width,y+8,3,48),StylizedArtDirection.LumenEnergy);GUI.Label(new Rect(x,y+3,width,30),front.IsOvertime?"OVERTIME":Format(front.TimeRemaining),front.IsOvertime?overtime:timer);float zero=front.ZeroControl/100f,lumen=1-zero,inner=width-20;Draw(new Rect(x+10,barY,inner,barH),new Color(.04f,.04f,.07f,.95f));Draw(new Rect(x+10,barY,inner*zero,barH),StylizedArtDirection.ZeroEnergy);Draw(new Rect(x+10+inner*zero,barY,inner*lumen,barH),StylizedArtDirection.LumenEnergy);float split=x+10+inner*zero;Draw(new Rect(split-2,barY-4,4,barH+8),Color.white);GUI.Label(new Rect(x+10,y+49,width*.42f,18),$"ZERO  {front.ZeroControl:0}%",team);GUI.Label(new Rect(x+width*.58f-10,y+49,width*.42f,18),$"{front.LumenControl:0}%  LUMEN",team);}
private void EnsureStyles(){label??=new GUIStyle(GUI.skin.label){fontSize=12,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};timer??=new GUIStyle(label){fontSize=20};overtime??=new GUIStyle(label){fontSize=21};team??=new GUIStyle(label){fontSize=11};}private void Draw(Rect r,Color c){Color old=GUI.color;GUI.color=c;GUI.DrawTexture(r,pixel);GUI.color=old;}private static string Format(float seconds){int total=Mathf.CeilToInt(seconds);return $"{total/60:00}:{total%60:00}";}private void OnDestroy(){if(pixel!=null)Destroy(pixel);}
}
}
